<script setup>
import {yuanMoney,estimate} from './trade-core.js';
const props=defineProps({row:{type:Object,required:true},editable:Boolean,busy:Boolean,stock:[Number,String]});
const emit=defineEmits(['quantity','select','remove']);
function select(event){const selected=event.target.checked;event.target.checked=props.row.selectedFlag===1;emit('select',selected);}
</script>
<template><div class="purchase-item" :data-row-id="row.id" :data-drug-id="row.drugId" :data-store-id="row.storeId"><input v-if="editable" type="checkbox" :aria-label="'选择'+row.drugName" :checked="row.selectedFlag===1" :disabled="busy" @change="select"><a class="purchase-photo" :href="'#detail?id='+row.drugId"><div class="product-photo missing"><Icon :name="row.isRx===1?'lock-keyhole':'package'"/><span>{{row.isRx===1?'处方药':'商品记录'}}</span></div></a><div class="purchase-name"><span v-if="row.isRx===1" class="tag rx">Rx 处方药 · 不可普通结算</span><a :href="'#detail?id='+row.drugId"><h3>{{row.drugName||'商品名称未提供'}}</h3></a><p>{{row.specification||'规格未提供'}}<span v-if="row.unit"> / {{row.unit}}</span></p><span v-if="stock!==undefined" class="small muted">当前可售量 {{stock}}</span></div><div class="item-unit"><span class="trade-price">¥{{yuanMoney(editable?(row.memberPrice??row.retailPrice):row.price)}}</span></div><div v-if="editable" class="quantity"><button :disabled="busy||row.qty<=1" :aria-label="'减少'+row.drugName+'数量'" @click="emit('quantity',row.qty-1)"><Icon name="minus"/></button><output>{{row.qty}}</output><button :disabled="busy" :aria-label="'增加'+row.drugName+'数量'" @click="emit('quantity',row.qty+1)"><Icon name="plus"/></button></div><span v-else class="small muted">× {{row.qty}}</span><strong class="item-subtotal">¥{{yuanMoney(editable?estimate([row]):row.lineAmount)}}</strong><button v-if="editable" class="icon-btn" :disabled="busy" :aria-label="'移除'+row.drugName" @click="emit('remove')"><Icon name="trash-2"/></button></div></template>
